from pathlib import Path
import html, json, re

ROOT = Path(__file__).resolve().parent
PAGES = []
def h(s): return html.escape(str(s))
def para(s): return '<p>'+s+'</p>'
def box(s): return '<aside class="note"><strong>ระวังในข้อสอบ</strong><p>'+s+'</p></aside>'
def section(title, text): return '<section><h2>'+title+'</h2>'+text+'</section>'
def ul(*s): return '<ul>'+''.join('<li>'+x+'</li>' for x in s)+'</ul>'
def steps(*s): return '<ol class="steps">'+''.join('<li>'+x+'</li>' for x in s)+'</ol>'
def table(headers, rows): return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def formula(s): return '<div class="formula">'+s+'</div>'
def code(s):
 lang='powershell' if 'python -m pip install' in s else 'python'
 return '<div class="code-wrap"><div class="code-toolbar"><span class="code-language">'+('PowerShell' if lang=='powershell' else 'Python')+' <small>One Dark Pro</small></span><div class="code-buttons"><button class="wrap-code" type="button" aria-pressed="false">ตัดบรรทัด</button><button class="expand-code" type="button" aria-expanded="false">ขยาย</button><button class="copy" type="button" aria-live="polite">คัดลอก</button></div></div><pre data-lang="'+lang+'" tabindex="0" aria-label="โค้ด '+lang+' เลื่อนอ่านได้"><code>'+h(s.strip())+'</code></pre></div>'
def recall(q,a): return '<details class="recall"><summary>'+q+'</summary><p>'+a+'</p></details>'
def add(slug,title,sub,body,tag='STUDY NOTES',source=''):
 PAGES.append(dict(slug=slug,title=title,sub=sub,body=body,tag=tag,source=source))
def src(n,topics):
 p=next((ROOT.parent/'lecture').glob(f'Chapter {n}_*.pdf'))
 return f'<a href="../lecture/{h(p.name)}" target="_blank">บท {n} · {topics}</a>'

