section('สูตรที่ต้องเขียนได้',table(['เรื่อง','สูตร / จำสั้น ๆ'],[('Linear','ŷ=β₀+Σβⱼxⱼ; residual=y−ŷ'),('Squared loss','SSE=Σe², MSE=SSE/n, RMSE=√MSE'),('Absolute loss','MAE=Σ|e|/n'),('R²','1−SSE/Σ(y−ȳ)²; ติดลบได้'),('Adjusted R²','1−(1−R²)(n−1)/(n−p−1)'),('Scaling','z=(x−μ_train)/σ_train'),('Ridge / Lasso','L2=Σβ² / L1=Σ|β|; Lasso ทำบาง coefficient เป็นศูนย์'),('Gaussian','φⱼ=exp(−.5((x−cⱼ)/σ)²); σ=width_factor×spacing'),('Logistic','p=1/(1+e⁻ᶻ); odds multiplier=exp(β)'),('Precision / Recall','TP/(TP+FP) / TP/(TP+FN)'),('F1 / Specificity','2TP/(2TP+FP+FN) / TN/(TN+FP)'),('Gini / Entropy','1−Σp² / −Σp log₂p'),('K-Means','Σ||x−μ_cluster||²; centers=mean'),('Silhouette','(b−a)/max(a,b)'),('Boosting','F_new=F_old+η×correction'),('CV cost','candidates×folds (+ final refit หากเปิด)'),('η²','SS_between/SS_total; ไม่ใช่เหตุและผล')]))
