CSS='''
:root{--ink:#172c32;--muted:#526c72;--paper:#f5f3ed;--card:#fff;--line:#dce3df;--green:#146c59;--lime:#d5f17e;--nav:#112f32;--orange:#bf652e}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.85 "Leelawadee UI","Tahoma",sans-serif}a{color:var(--green);text-underline-offset:4px}button,select,input,textarea{font:inherit}button,.pill{border:0;border-radius:9px;background:var(--green);color:white;padding:9px 17px;cursor:pointer;text-decoration:none;display:inline-block;font-size:14px}button:hover,.pill:hover{filter:brightness(1.12)}button:disabled{cursor:not-allowed;opacity:.45}.secondary{background:#e4eae5;color:var(--ink)}:focus-visible{outline:3px solid #bc7b22;outline-offset:3px}h1,h2,h3,p{margin-top:0}h1{font-size:clamp(28px,3vw,42px);line-height:1.35;letter-spacing:-.8px;margin-bottom:14px}h2{font-size:24px;line-height:1.5;margin-bottom:18px}h3{font-size:19px}p{margin-bottom:17px}small{display:block}.eyebrow{font-size:11px;font-weight:800;letter-spacing:2px;color:var(--green)}.page{max-width:1100px;margin:auto;padding:45px 50px 80px}.page-header{padding-bottom:28px;border-bottom:1px solid var(--line);margin-bottom:30px}.subtitle{color:var(--muted);font-size:17px}.page-actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:20px}.toc{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:24px}.toc a{font-size:12px;padding:5px 10px;background:white;border:1px solid var(--line);border-radius:6px;text-decoration:none}.hero{background:var(--nav);color:#f3f6e9;padding:44px;border-radius:18px;margin-bottom:32px;position:relative;overflow:hidden}.hero:after{content:"";position:absolute;width:200px;height:200px;border:1px solid #52776b;border-radius:50%;right:-70px;top:40px;box-shadow:0 0 0 35px #ffffff05,0 0 0 70px #ffffff05}.hero h2{font-size:clamp(32px,4vw,50px);line-height:1.45;margin:18px 0}.hero p{max-width:650px;color:#ccd9ce}.hero .eyebrow{color:var(--lime)}.hero-stats{display:flex;gap:45px;margin-top:30px}.hero-stats b{font-size:32px;color:var(--lime)}.hero-stats small{font-size:12px;color:#d5dfd6;font-weight:400}section{background:var(--card);border:1px solid var(--line);padding:28px 32px;margin:22px 0;border-radius:13px;scroll-margin-top:20px}section>h2:before{content:"";display:inline-block;background:var(--green);width:5px;height:22px;margin-right:12px;vertical-align:middle;border-radius:2px}.table-wrap{overflow:auto;margin:18px 0}table{width:100%;border-collapse:collapse;font-size:14px;line-height:1.8}th{text-align:left;background:#eaf0e9;font-size:13px}td,th{padding:12px 15px;border-bottom:1px solid var(--line);vertical-align:top}td:first-child{font-weight:600;min-width:120px}tr:last-child td{border-bottom:0}.formula{background:#edf3e5;border-left:4px solid var(--green);border-radius:6px;padding:18px 22px;font-family:"Consolas","Leelawadee UI",sans-serif;overflow-wrap:anywhere;margin:20px 0}.note{background:#fff5e2;border-left:4px solid #c18137;padding:20px 24px;margin:22px 0;border-radius:6px}.note p:last-child,section>p:last-child{margin-bottom:0}.note strong{color:#88511c}.steps li{padding:6px 0 10px 10px}.steps li::marker{color:var(--green);font-weight:800}li{margin-bottom:8px}pre{background:#142c31;color:#e6eddf;padding:45px 22px 22px;overflow:auto;border-radius:9px;line-height:1.65;font-size:13px;tab-size:4}.code-wrap{position:relative}.copy{position:absolute;right:9px;top:9px;padding:3px 11px;font-size:12px;background:#39544d}.recall{background:#eef4ef;margin:12px 0;border-radius:8px;padding:15px 20px}.recall summary{cursor:pointer;font-weight:600}.recall p{margin:14px 0 0}.source{font-size:12px;color:var(--muted);border-top:1px solid var(--line);margin-top:35px;padding-top:20px}.bottom-nav{display:flex;justify-content:space-between;gap:20px;margin-top:25px}.bottom-nav a{text-decoration:none;font-size:14px}.flow{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:20px 0}.flow span{background:#eaf2e6;padding:12px;border-radius:8px}.toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;position:sticky;top:0;z-index:3;background:var(--paper);padding:12px 0}select{border:1px solid var(--line);padding:8px;border-radius:8px;background:white}.question{padding:24px;background:white;border:1px solid var(--line);border-radius:12px;margin:16px 0}.question legend{font-weight:700;line-height:1.7;padding:0 5px}.question label{display:flex;align-items:flex-start;gap:10px;padding:10px 14px;border:1px solid var(--line);border-radius:8px;margin:9px 0;cursor:pointer}.question label:has(input:checked){background:#e9f2d9;border-color:var(--green)}.question input{margin-top:8px;accent-color:var(--green)}.question.correct{border-left:5px solid #22846a}.question.incorrect{border-left:5px solid #c06c3c}.feedback{background:#f0f5e7;padding:15px;margin-top:15px;border-radius:7px;font-size:14px}.question.incorrect .feedback{background:#fff2e5}.result-card{background:var(--nav);color:white;padding:24px;border-radius:12px;margin:20px 0}.result-card h2{color:var(--lime);margin-bottom:8px}.result-card a{color:var(--lime)}.exam-bar{position:sticky;top:0;background:#e7eddf;padding:16px;border-radius:10px;display:flex;align-items:center;gap:12px;flex-wrap:wrap;z-index:3}#timer{font:700 26px Consolas,monospace;min-width:95px}textarea{width:100%;min-height:170px;padding:15px;border:1px solid #b8c8be;border-radius:8px;color:var(--ink);background:#fafbf6;resize:vertical}.self-score{width:85px;padding:5px;border:1px solid var(--line)}img{max-width:100%;height:auto;border-radius:8px}.chapter-chip{font-size:11px;color:var(--green);font-weight:700}.muted{color:var(--muted);font-size:13px}.storage-warning{background:#fff1d9;padding:10px;border-radius:8px}.shell{display:grid;grid-template-columns:265px 1fr;height:100dvh;overflow:hidden}.sidebar{background:var(--nav);color:#dce7df;overflow:auto;padding:26px 20px}.brand{font:700 22px/1.3 Georgia,serif;color:var(--lime);margin-bottom:6px}.brand small{font:11px/1.7 Tahoma,sans-serif;color:#b0c6bd;letter-spacing:2px}.sidebar hr{border:0;border-top:1px solid #355250;margin:24px 0}.nav-label{font-size:10px;letter-spacing:2px;color:#8eada1;margin:24px 10px 8px}.sidebar a{display:block;color:#c6d8ce;font-size:13px;text-decoration:none;padding:10px 12px;border-radius:7px;margin:4px 0}.sidebar a:hover{background:#23473f}.sidebar a.active{background:var(--lime);color:#1b392e;font-weight:700}.sidebar a.done:not(.active):after{content:" ✓";color:var(--lime)}.side-foot{font-size:11px;color:#a4bdb0;margin:24px 10px}.workspace{min-width:0;display:flex;flex-direction:column}.topbar{height:65px;flex-shrink:0;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:18px;padding:12px 28px}.topbar input{width:100%;max-width:480px;border:1px solid var(--line);border-radius:8px;background:#f8f9f5;padding:8px 14px;font-size:13px}.topbar .status{margin-left:auto;color:var(--muted);font-size:11px;white-space:nowrap}.menu-toggle{display:none}iframe{border:0;width:100%;flex:1;background:var(--paper)}#search-results{position:absolute;z-index:10;top:60px;left:290px;right:25px;max-height:70vh;overflow:auto;background:white;box-shadow:0 12px 40px #1234;border:1px solid var(--line);border-radius:12px;padding:15px}#search-results[hidden]{display:none}.search-hit{display:block;border-bottom:1px solid var(--line);padding:12px;text-decoration:none}.search-hit small{color:var(--muted)}.no-js{padding:20px;background:#fff1d9}
@media(max-width:900px){.shell{grid-template-columns:220px 1fr}.sidebar{padding:20px 12px}.page{padding:30px 24px}.hero{padding:30px}section{padding:22px}.topbar{padding:10px 18px}#search-results{left:230px}.hero-stats{gap:28px}}
@media(max-width:650px){.shell{display:flex}.sidebar{position:fixed;top:65px;bottom:0;left:0;width:260px;z-index:20;transform:translateX(-100%);transition:transform .2s}.shell.menu-open .sidebar{transform:translateX(0)}.workspace{width:100%}.menu-toggle{display:block;font-size:12px;padding:7px 10px}.topbar{gap:10px;padding:10px}.topbar .status{display:none}.page{padding:26px 16px}.page h1{font-size:28px}section{padding:20px 17px}.hero{padding:27px 23px}.hero h2{font-size:35px}.hero-stats{gap:25px}h2{font-size:21px}td,th{padding:9px 11px}#search-results{left:12px;right:12px}.toolbar{position:static}.exam-bar{gap:8px}.exam-bar button{font-size:12px;padding:7px 10px}}
@media print{body{background:white;color:black;font-size:11pt}.page{max-width:none;padding:0}.page-actions,.copy,.toolbar,.exam-bar,.bottom-nav,.toc{display:none}section{break-inside:auto;border:0;padding:0;margin:18pt 0}h2,h3{break-after:avoid}.hero{background:#edf2e7!important;color:black;padding:20px}.hero p,.hero small,.hero .eyebrow,.hero-stats b{color:black}.question{break-inside:avoid}pre{white-space:pre-wrap;background:#eee;color:black;font-size:9pt}.formula,.note{break-inside:avoid}a{color:black}details{display:block}details>*{display:block}.shell{display:block;height:auto}.sidebar,.topbar{display:none}iframe{height:100vh}}
'''
(ROOT/'style.css').write_text(CSS+'\n'+(ROOT/'qa-overrides.css').read_text(encoding='utf-8'),encoding='utf-8')
menu=[{k:p[k] for k in ('slug','title','sub','tag')} for p in PAGES]
for i,p in enumerate(PAGES):
 body=p['body']
 count=[0]
 def heading(match):
  count[0]+=1
  return f'<h2 id="s{count[0]}">{match.group(1)}</h2>'
 body=re.sub(r'<h2>(.*?)</h2>',heading,body)
 toc=''.join(f'<a href="#{h(anchor)}">{h(re.sub("<[^>]+>","",t))}</a>' for anchor,t in re.findall(r'<h2[^>]* id="([^"]+)"[^>]*>(.*?)</h2>',body))
 payload=''
 if p['slug'] in ('quiz','mock-exam'):
  payload='<script>window.assessmentData='+json.dumps(dict(kind=p['slug'],questions=QUIZ if p['slug']=='quiz' else MOCK,written=WRITTEN if p['slug']=='mock-exam' else []),ensure_ascii=False).replace('</',r'<\/')+';</script><script src="assessment.js?v=20261027q3"></script>'
 if p['slug'].startswith('quick-quiz-'):
  number=int(p['slug'][-1])
  payload='<script>window.quickData='+json.dumps(dict(slug=p['slug'],titles=TITLES,questions=SETS[number]),ensure_ascii=False).replace('</',r'<\/')+';</script><script src="quick-quiz.js?v=20261027q3"></script>'
 prev=PAGES[i-1] if i else None; nxt=PAGES[i+1] if i+1<len(PAGES) else None
 nav='<nav class="bottom-nav">'+(f'<a href="{prev["slug"]}.html">← {h(prev["title"])}</a>' if prev else '<span></span>')+(f'<a href="{nxt["slug"]}.html">{h(nxt["title"])} →</a>' if nxt else '')+'</nav>'
 doc=f'''<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="สรุป Data Science บท 7–12 สูตร โค้ด Python Quiz และ Mock Exam พร้อมเฉลยภาษาไทย"><title>{h(p['title'])} | Data Science Exam Notes</title><link rel="stylesheet" href="style.css?v=20261027q3"></head><body data-page="{p['slug']}"><main class="page"><header class="page-header"><span class="eyebrow">{p['tag']} / CP352101</span><h1>{h(p['title'])}</h1><p class="subtitle">{h(p['sub'])}</p><div class="page-actions"><button id="mark-read" class="secondary">ทำเครื่องหมายอ่านแล้ว</button><button class="secondary" onclick="window.print()">พิมพ์หมวดนี้ / PDF</button><a class="pill secondary" href="../index.html#{p['slug']}" target="_top">หน้ารวม</a></div></header><nav class="toc" aria-label="สารบัญในหมวด">{toc}</nav>{body}<footer class="source">ที่มา: {p['source'] or 'เรียบเรียงเพื่อทบทวนจากเอกสารในโฟลเดอร์ ดูรายละเอียดที่หน้าแหล่งข้อมูล'}<br>สื่อเตรียมสอบ · ข้อมูลตัวอย่างเป็นข้อมูลจำลอง · เกณฑ์สอบจริงให้ยึดประกาศผู้สอน</footer>{nav}</main><script src="page.js?v=20261027q3"></script>{payload}</body></html>'''
 (ROOT/(p['slug']+'.html')).write_text(doc,encoding='utf-8')

nav=''
for tag,label in [('STUDY NOTES','LEARN / บทเรียน'),('PROCESS','CONNECT / กระบวนการ'),('QUICK REFERENCE','RECALL / สูตรและโค้ด'),('PYTHON LAB',''),('VERIFIED OUTPUT',''),('QUICK QUIZ','QUICK QUIZ / ฝึกแยกบท'),('PRACTICE','PRACTICE / ทดสอบตัวเอง'),('MOCK EXAM',''),('SOURCE MAP','REFERENCE')]:
 if label: nav+=f'<div class="nav-label">{label}</div>'
 for p in PAGES:
  if p['tag']==tag: nav+=f'<a href="#{p["slug"]}" data-slug="{p["slug"]}">{h(p["title"])}</a>'
search=[]
for p in PAGES:
 text=re.sub('<[^>]+>',' ',p['body']);
 if p['slug'] in ('quiz','mock-exam'): text+=' '+' '.join(q['stem'] for q in (QUIZ if p['slug']=='quiz' else MOCK))
 if p['slug'].startswith('quick-quiz-'): text+=' '+' '.join(q['stem'] for q in SETS[int(p['slug'][-1])])
 text=html.unescape(re.sub(r'\s+',' ',text))
 search.append(dict(slug=p['slug'],title=p['title'],text=text))
(ROOT/'search-data.js').write_text('window.sitePages='+json.dumps(menu,ensure_ascii=False)+';window.searchData='+json.dumps(search,ensure_ascii=False)+';',encoding='utf-8')
index=f'''<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="สรุป Data Science บท 7–12 สูตร โค้ด Python Quiz และ Mock Exam พร้อมเฉลยภาษาไทย"><title>Data Science · Exam Notes 07–12</title><link rel="stylesheet" href="exam-prep/style.css?v=20261027q3"></head><body><a class="skip-link" href="#reader" onclick="document.getElementById('reader').focus();return false">ข้ามไปเนื้อหา</a><div class="shell" id="shell"><aside class="sidebar" id="sidebar"><div class="brand">Data Science<small>EXAM NOTES / 07—12</small></div><hr><nav aria-label="หมวดสรุป">{nav}</nav><div class="side-foot"><span id="progress">อ่านแล้ว 0 หมวด</span><br>LOCAL STUDY KIT · ใช้งานออฟไลน์</div></aside><div class="workspace"><header class="topbar"><button class="menu-toggle" aria-controls="sidebar" aria-expanded="false">เมนู</button><input id="search" type="search" aria-label="ค้นหาทุกหมวด" placeholder="ค้นหาแนวคิด สูตร หรือชื่อโมเดล…"><span class="status">CP352101 · EXAM PREPARATION</span></header><div id="search-results" hidden></div><iframe id="reader" name="reader" tabindex="0" title="เนื้อหาสรุปเตรียมสอบ" src="exam-prep/overview.html"></iframe></div></div><noscript><div class="no-js">เปิด JavaScript เพื่อใช้เมนู Quiz และ Mock Exam หรืออ่านแยกไฟล์: {''.join(f'<a href="exam-prep/{p["slug"]}.html">{h(p["title"])}</a> · ' for p in PAGES)}</div></noscript><script src="exam-prep/search-data.js?v=20261027q3"></script><script src="exam-prep/shell.js?v=20261027q3"></script></body></html>'''
(ROOT.parent/'index.html').write_text(index,encoding='utf-8')
print(f'Built {len(PAGES)} category pages + root index.html; Quiz {len(QUIZ)}; Mock {len(MOCK)} + {len(WRITTEN)} written')
